//! Map areas actions preserve actual native paint and editor/link state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn map_areas_actual_app_pointer_attribute_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-map-areas-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}map{display:block;position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}map[name="ready"]{background:#cc2244}map[name="done"]{background:#2244cc}map:not([name]){background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><map id=map name=initial>Fallback map<area id=first name=alpha><span id=nested><area id=second name=beta></span></map><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Change metadata</button><div id=destination></div><script>var x=document.getElementById('map'),list=x.areas,one=document.getElementById('first'),two=document.getElementById('second'),nested=document.getElementById('nested'),third,attr=x.getAttributeNode('name'),first=x.firstChild,round=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'native pointer';var focus=document.activeElement;if(round===0){third=document.createElement('area');third.setAttribute('id','gamma');x.appendChild(third);x.name='ready';}else if(round===1){x.removeChild(one);attr.nodeValue='done';}else{nested.removeChild(two);x.removeAttribute('name');}var records=watch.takeRecords();if(list!==x.areas||list.length!==[3,2,1][round]||list.namedItem('gamma')!==third||x.name!==['ready','done',''][round]||x.firstChild!==first||x.textContent!=='Fallback map'||records.length!==1||records[0].attributeName!=='name'||records[0].oldValue!==['initial','ready','done'][round]||document.activeElement!==focus||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual name state';if(round<2){if(attr.ownerElement!==x||x.getAttributeNode('name')!==attr)throw 'same actual Attr';}else{if(attr.ownerElement!==null||attr.value!=='done')throw 'removed Attr';}document.title='Map areas '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);let initial=app.draw();assert_eq!(initial.pixels[(app.content_top()+40)as usize*initial.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert!(!app.failed,"{}",app.status);assert_eq!(app.document.title,format!("Map areas {round}"));let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],[0xcc2244,0x2244cc,0x228844][round]);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
